mapper.select:
SELECT g.*, r.name AS rule_name, s.name AS store_name, s.platform, l.title
FROM ecom_reprice_log g
LEFT JOIN ecom_reprice_rule r ON r.id = g.rule_id
LEFT JOIN ecom_store s ON s.id = g.store_id
LEFT JOIN ecom_listing l ON l.id = g.listing_id

    g.rule_id = #{ruleId}
    AND g.store_id = #{storeId}
    AND g.status = #{status}
    AND g.run_time >= #{begin}
    AND g.run_time < #{end}
    AND (g.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR l.title LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY g.id DESC
